c=canvas.Canvas(str(OUT/'Maison_Rue_Website_Introduction.pdf'),pagesize=(960,540))
c.setTitle('Maison Rue Website Introduction'); c.setAuthor('Maison Rue')
style=ParagraphStyle('body',fontName='Helvetica',fontSize=12.8,leading=18,textColor=HexColor('#51463d'))
for n,(label,title,intro,items) in enumerate(pages,1):
 c.setFillColor(HexColor('#f7f4ee')); c.rect(0,0,960,540,fill=1,stroke=0)
 c.setFillColor(HexColor('#91764e')); c.setFont('Helvetica',10); c.drawString(54,500,label.upper())
 c.setFillColor(HexColor('#302720')); c.setFont('Times-Roman',34); c.drawString(54,450,title)
 p=Paragraph(intro,style); w,h=p.wrap(850,90); p.drawOn(c,54,425-h)
 y=336
 for head,body in items:
  c.setFillColor(HexColor('#302720')); c.setFont('Helvetica-Bold',12); c.drawString(54,y,head)
  p=Paragraph(body,style); w,h=p.wrap(850,95); p.drawOn(c,54,y-10-h); y-=h+39
 c.setFillColor(HexColor('#91764e')); c.setFont('Helvetica',9); c.drawString(54,24,'MAISON RUE  |  WEBSITE INTRODUCTION'); c.drawRightString(906,24,f'{n:02d} / {len(pages):02d}')
 c.showPage()
c.save()
